mapper.select:
select count(*) as total, avg(svr_satisfaction_score) as avgScore
from t_survey_response
where 1 = 1

    and svr_template_id = #{templateId}


    and svr_submitted_at >= #{from}


    and svr_submitted_at <= #{to}

select round(svr_satisfaction_score / 10) as bucket, count(*) as count
from t_survey_response
where 1 = 1

    and svr_template_id = #{templateId}


    and svr_submitted_at >= #{from}


    and svr_submitted_at <= #{to}

group by round(svr_satisfaction_score / 10)
order by bucket

select r.svr_id as responseId, r.svr_candidate_id as candidateId, r.svr_satisfaction_score as satisfactionScore, cast(r.svr_answers as char) as answers, date_format(r.svr_submitted_at, '%Y-%m-%d %H:%i') as submittedAt, u.nick_name as candidateName, svt.svt_name as templateName from t_survey_response r left join t_tal t on t.tal_id = r.svr_candidate_id left join sys_user u on u.user_id = t.tal_user_id left join t_survey_template svt on svt.svt_id = r.svr_template_id where 1 = 1
and r.svr_template_id = #{templateId}
and r.svr_submitted_at >= #{from}
and r.svr_submitted_at <= #{to}
order by r.svr_submitted_at desc
